package br.gov.dere.persistence;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="dere_entity") public class DereEntityEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="cnpj_root",nullable=false,unique=true) private String cnpjRoot; @Column(name="legal_name",nullable=false) private String legalName; private boolean active=true; @Column(name="created_at") private Instant createdAt=Instant.now(); @ManyToMany(mappedBy="entities") private Set<DereUserEntity> users=new HashSet<>(); protected DereEntityEntity(){} public DereEntityEntity(String c,String n){cnpjRoot=c;legalName=n;} public Long getId(){return id;} public String getCnpjRoot(){return cnpjRoot;} public String getLegalName(){return legalName;} public Set<DereUserEntity> getUsers(){return users;} public void update(String c,String n){cnpjRoot=c;legalName=n;}}
